from html import escape as esc
import json
from collections import Counter
ROOT=Path(__file__).resolve().parents[3]
OUT=ROOT/'docs/reviews/certification-v5-audit.html'
RUNS=['certification-2026-10-02-run2','certification-2026-10-02-interactions','certification-2026-10-02-completion']
base=ROOT/'artifacts/visual-review'
