captures=[(r,c) for r,m in zip(RUNS,manifests) for c in m['captures'] if c['id']!='blocked']
violations=Counter(); failing=0
for r,c in captures:
 v=json.loads((base/r/(c['id']+'.axe.json')).read_text());failing+=bool(v)
 for x in v:violations[x['id']]+=len(x['nodes'])
def evidence(id,label=None):
 for r,c in reversed(captures):
  if c['id']==id:return f'<a href="../../artifacts/visual-review/{r}/{id}.png">{esc(label or id)}</a>'
 return f'<strong>MISSING EVIDENCE: {esc(id)}</strong>'
def source(path,line):return f'<a href="../../{path}"><code>{esc(path)}:{line}</code></a>'
def finding(priority,title,body,proof):return f'<article class="finding"><h3><span class="tag">{priority}</span> {title}</h3><p>{body}</p><p class="evidence">Evidence: {proof}</p></article>'
