for r,c in captures:
 id=c['id'];prefix=f'../../artifacts/visual-review/{r}/{id}'
 gallery+=f'<details class="capture" data-name="{id}"><summary>{id} · {c["viewport"]["width"]}×{c["viewport"]["height"]}</summary><p><a href="{prefix}.png">Full image</a> · <a href="{prefix}.txt">Accessible snapshot</a> · <a href="{prefix}.axe.json">Accessibility findings</a></p><img loading="lazy" src="{prefix}.png" alt="Captured certification state: {id}"></details>'
